export interface Settings {
  executionMode: SettingsExecutionMode;
  /** Max risk per trade as percentage of account (default 1%) */
  maxRiskPerTrade: number;
  /** Max portfolio risk as percentage (default 10%) */
  maxPortfolioRisk: number;
  profitTarget50: number;
  profitTarget75: number;
  profitTarget90: number;
  /** Stop loss as multiple of credit received (default 2x) */
  stopLossMultiplier: number;
  /** Whether the most recent Alpaca Paper Trading broker health check (GET /broker/health) authenticated successfully — computed, never client-settable, and honestly false until a check has actually been performed */
  alpacaConnected: boolean;
  /** @nullable */
  alpacaApiKey?: string | null;
  /** Scanner data mode — mock (simulated) or live (provider chains) */
  scannerMode?: SettingsScannerMode;
  /** Preferred options-data provider when in live mode */
  marketDataProvider?: SettingsMarketDataProvider;
  /** Default days to expiry (default 45) */
  defaultDte?: number;
  /** Default short delta (default 0.20) */
  shortDelta?: number;
  /** Minimum IV rank to consider trades */
  minIvRank?: number;
  /** Full-auto master switch / kill switch (default false) */
  autoExecuteEnabled?: boolean;
  autoMaxTradesPerDay?: number;
  autoMaxConcurrentPositions?: number;
  autoMinRavishScore?: number;
  autoMaxDailyLossPct?: number;
  autoQuantityPerTrade?: number;
  /** Net |delta| at which a position is flagged for adjustment */
  adjDeltaDriftTrigger?: number;
  /** POP drop (points vs entry) that flags a position */
  adjPopDropTrigger?: number;
  /** Spot-to-short-strike distance (%) considered "tested" */
  adjShortStrikeProximityPct?: number;
  /** IV expansion (% vs entry IV) that flags a position */
  adjIvExpansionTrigger?: number;
  /** DTE at/under which gamma-management kicks in */
  adjDteTrigger?: number;
  /** Auto-adjustment master switch (close/de-risk only) */
  autoAdjustEnabled?: boolean;
  /** Event Risk Filter master switch */
  eventRiskEnabled?: boolean;
  /** Block opening short-premium trades before earnings */
  eventRiskBlockEarningsShortPremium?: boolean;
  /** Block AutoPilot auto-execution when event risk is high */
  eventRiskAutoBlockHigh?: boolean;
  /** Value-investing fundamentals provider (only "simulated" is wired today) */
  fundamentalsProvider?: SettingsFundamentalsProvider;
  /** Whether a live fundamentals provider is configured (always false today) */
  fundamentalsConnected?: boolean;
  /**
     * ISO timestamp of the most recent successful live fundamentals fetch (null if a live provider has never been reached this process)
     * @nullable
     */
  fundamentalsLastFetchedAt?: string | null;
  /** How old (in hours) live fundamentals may be before the UI flags them as stale and nudges a refresh (defaults to 24) */
  fundamentalsStalenessHours?: number;
  /** Auto re-fetch live fundamentals once data crosses the staleness threshold (no effect for simulated data) */
  fundamentalsAutoRefresh?: boolean;
  /** Risk-free rate assumption for the Investing Engine's valuation models (default 0.045, matches the options engine's RISK_FREE constant) */
  investingRiskFreeRate?: number;
  /** Default discount-rate assumption for the Investing Engine's DCF/Buffett valuation models (default 0.09) */
  investingDefaultDiscountRate?: number;
  /** Filings data source for Annual Report Analysis (only "edgar" is wired today) */
  investingFilingsProvider?: string;
  /** Institutional Trading Engine market-data provider (only "simulated" is wired today) */
  tradingDataProvider?: string;
  /** Whether a live trading market-data provider is configured (always false today) */
  tradingDataConnected?: boolean;
  /**
     * Account value used to size Engine 2 (trading) position risk — distinct from Engine 3's options-derived account value; null until the user sets it
     * @nullable
     */
  tradingAccountValue?: number | null;
  /** Whether the in-app notification center generates alerts for this user (watchlist target-crossing, risk hard-cap breach); default true */
  alertsEnabled?: boolean;
}

